def ruta():
    return os.environ.get('PULSO_DB', 'pulso.db')


# Cuánto espera una conexión a que otra (de cualquier proceso) libere la base antes de fallar.
ESPERA_SEGUNDOS = 30


def _abrir():
    con = sqlite3.connect(ruta(), timeout=ESPERA_SEGUNDOS)
    con.row_factory = sqlite3.Row
    con.execute('PRAGMA foreign_keys = ON')
    return con


@contextmanager
def conexion():
    con = _abrir()
    try:
        yield con
        con.commit()
    finally:
        con.close()


@contextmanager
def transaccion():
    """Transacción de escritura: toma el lock de escritura de SQLite antes de leer.

    Así, las lecturas y escrituras de adentro no se intercalan con las de otro pedido,
    aunque venga de otro proceso. Si hay un error (o un HTTPException), se revierte todo.
    Hay que hacer COMMIT explícitamente al terminar (no alcanza con salir del with).
    """
    con = _abrir()
    con.isolation_level = None
    try:
        con.execute('BEGIN IMMEDIATE')
        yield con
        con.execute('COMMIT')
    except BaseException:
        if con.in_transaction:
            con.execute('ROLLBACK')
        raise
    finally:
        con.close()

